//: 💡 示例 1：检查用户年龄并判断是否成年
function checkAdult(age) {
  // 验证输入年龄是否大于等于 18 岁
  if (age >= 18) {
    return true;
  } else {
    return false;
  }
}

//: 💡 示例 2：使用 for 循环计算 1 到 N 的累加和
function calculateSum(n) {
  let total = 0;
  for (let i = 1; i <= n; i++) {
    total += i;
  }
  return total;
}
